206		return left.digest < right.digest ? -1 : left.digest > right.digest ? 1 : 0;
207	}
208	
209	function plainRecord(value: unknown): value is Readonly<Record<string, unknown>> {
210		return value !== null && typeof value === "object" && !Array.isArray(value);
211	}
212	
213	function successfulValue<T>(value: unknown): T | undefined {
214		if (!plainRecord(value) || value.ok !== true || !Object.hasOwn(value, "value")) return undefined;
215		return value.value as T;
216	}
217	
218	function successfulUndefined(value: unknown): boolean {
219		return plainRecord(value) && value.ok === true && Object.hasOwn(value, "value") && value.value === undefined;
220	}
221	
222	function refFor(bytes: Uint8Array): GenerationRef {
223		const digest = digestBlob(bytes);
224		if (!digest.ok) throw new TypeError("creator close blob digest failed");
225		return Object.freeze({ byteLength: bytes.byteLength, digest: digest.value });
226	}
227	
228	function sameRef(left: GenerationRef, right: GenerationRef): boolean {
229		return left.byteLength === right.byteLength && left.digest === right.digest;
230	}
231	
232	function hex(bytes: Uint8Array): string {
233		return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
234	}
