238	function uniqueRecordCandidate(
239		candidates: InspectedHead["candidates"],
240		kind: string,
241		epoch?: number,
242		phase?: string
243	): InspectedHead["candidates"][number] | undefined {
244		const matches = candidates.filter((candidate) => {
245			try {
246				const value = decodeCanonical(candidate.bytes);
247				return (
248					plainRecord(value) &&
249					value.kind === kind &&
250					(epoch === undefined ||
251						(value.kind === "drp-anchor-trust-state" ? value.currentEpoch : value.epoch) === epoch) &&
252					(phase === undefined || value.phase === phase)
253				);
254			} catch {
255				return false;
256			}
257		});
258		return matches.length === 1 ? matches[0] : undefined;
259	}
