261	async function issuanceRetirementCandidate(
262		input: Readonly<{
263			current: InspectedHead;
264			currentTrust: CurrentAnchorTrust;
265			cutValueDigest: string;
266			durableReplay: Readonly<{ verify(): Promise<boolean> }>;
267			graph: Exclude<ReturnType<V3CreatorCloseRegistration["captureCloseGraph"]>, undefined>;
268			issuanceScope: DurableIssueScope;
269			issuanceStore: DurableIssuanceStore;
270			maxEpochVertices: number;
271			qcRef: GenerationRef;
272			signer: FinalitySigner;
273			snapshotManifestDigest: string;
274			successorTrust: CurrentAnchorTrust;
275		}>
276	): Promise<Readonly<{ bytes: Uint8Array; priorRef?: GenerationRef; ref: GenerationRef }>> {
277		if (!(await input.durableReplay.verify())) throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
278		let priorAdmittedAuthorSequence: number | null = null;
279		let priorRetirementCandidateDigest = CREATOR_ISSUANCE_RETIREMENT_GENESIS_SENTINEL;
280		let priorRef: GenerationRef | undefined;
281		if (input.currentTrust.currentEpoch > 0) {
282			const candidate = uniqueRecordCandidate(input.current.candidates, CREATOR_ISSUANCE_RETIREMENT_KIND);
283			const cut = uniqueRecordCandidate(
284				input.current.candidates,
285				"drp-hard-epoch-cut",
286				input.currentTrust.currentEpoch - 1
287			);
288			const qc = uniqueRecordCandidate(
289				input.current.candidates,
290				"drp-seal-qc",
291				input.currentTrust.currentEpoch - 1,
292				"commit"
293			);
294			if (candidate === undefined || cut === undefined || qc === undefined) {
295				throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
296			}
297			const cutRecord = decodeCanonical(cut.bytes);
298			if (!plainRecord(cutRecord) || typeof cutRecord.snapshotManifestDigest !== "string") {
299				throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
300			}
301			const opened = openCreatorIssuanceRetirement({
302				exactCanonicalRecordBytes: candidate.bytes,
303				expectedCommitQcRef: qc.ref,
304				expectedCutValueDigest: hex(hashDomain("ts-drp/hard-epoch-cut/v3", cut.bytes)),
305				expectedSnapshotManifestDigest: cutRecord.snapshotManifestDigest,
306				floorTrust: input.currentTrust,
307			});
308			const identity = opened.ok ? resolveCreatorIssuanceRetirement(opened.capability) : undefined;
309			if (identity === undefined || identity.author !== input.issuanceScope.author) {
310				throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
311			}
312			priorAdmittedAuthorSequence = identity.admittedAuthorSequence;
313			priorRetirementCandidateDigest = candidate.ref.digest;
314			priorRef = candidate.ref;
315		}
316		const boundary = await deriveCreatorIssuanceRetirementBoundary({
317			currentAnchorDigest: input.currentTrust.currentAnchorDigest,
318			currentEpoch: input.currentTrust.currentEpoch,
319			graphVertexDigests: input.graph.vertices,
320			issuanceScope: input.issuanceScope,
321			issuanceStore: input.issuanceStore,
322			maxEpochVertices: input.maxEpochVertices,
323			priorAdmittedAuthorSequence,
324		});
325		const prepared = prepareCreatorIssuanceRetirement({
326			admittedAuthorSequence: boundary.admittedAuthorSequence,
327			author: input.issuanceScope.author,
328			commitQcRef: input.qcRef,
329			currentTrust: input.currentTrust,
330			cutValueDigest: input.cutValueDigest,
331			observedLineage: boundary.observedLineage,
332			priorAdmittedAuthorSequence,
333			priorRetirementCandidateDigest,
334			snapshotManifestDigest: input.snapshotManifestDigest,
335			successorTrust: input.successorTrust,
336		});
337		if (!prepared.ok) throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
338		const signature = await signCreatorIssuanceRetirementRequest({
339			request: prepared.signingRequest,
340			signer: input.signer,
341		});
342		const completed = completeCreatorIssuanceRetirement({
343			detachedSignature: signature,
344			preparation: prepared.preparation,
345		});
346		if (!completed.ok) throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
347		const ref = refFor(completed.exactCanonicalRecordBytes);
348		return Object.freeze({
349			bytes: Uint8Array.from(completed.exactCanonicalRecordBytes),
350			...(priorRef === undefined ? {} : { priorRef: copiedRef(priorRef) }),
351			ref,
352		});
353	}
354	
355	function sameHead(left: PresentHead, right: PresentHead): boolean {
356		return (
357			left.closureDigest === right.closureDigest &&
358			left.generationId === right.generationId &&
359			left.objectId === right.objectId &&
360			left.revision === right.revision
361		);
362	}
363	
364	function generationId(): GenerationId {
365		const bytes = new Uint8Array(32);
366		crypto.getRandomValues(bytes);
367		const parsed = parseGenerationId(Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join(""));
368		if (!parsed.ok) throw new TypeError("creator close generation identity failed");
369		return parsed.value;
370	}
