372	async function inspectHead(
373		store: AheDurableStore,
374		objectId: Parameters<AheDurableStore["recoverActiveGeneration"]>[0]
375	): Promise<
376		Readonly<{
377			candidates: readonly Readonly<{ bytes: Uint8Array; ref: GenerationRef }>[];
378			head: PresentHead;
379			references: readonly GenerationRef[];
380			trustRef: GenerationRef;
381		}>
382	> {
383		const recovered = successfulValue<Readonly<Record<string, unknown>>>(await store.recoverActiveGeneration(objectId));
384		if (recovered?.kind !== "active" || !plainRecord(recovered.head) || !Array.isArray(recovered.references)) {
385			throw new TypeError("creator close active generation is unavailable");
386		}
387		const references = Object.freeze((recovered.references as GenerationRef[]).map(copiedRef));
388		const candidates: Array<Readonly<{ bytes: Uint8Array; ref: GenerationRef }>> = [];
389		for (const ref of references) {
390			if (ref.byteLength > SCANNABLE_BYTES) continue;
391			const bytes = successfulValue<Uint8Array | null>(await store.getBlob(ref.digest));
392			if (!(bytes instanceof Uint8Array)) throw new TypeError("creator close generation blob is unavailable");
393			candidates.push(Object.freeze({ bytes: Uint8Array.from(bytes), ref }));
394		}
395		const inspected = inspectTrustClosure({ candidates, closure: references });
396		if (!inspected.ok) throw new TypeError(`creator close trust scan failed: ${inspected.reason}`);
397		return Object.freeze({
398			candidates: Object.freeze(candidates),
399			head: Object.freeze({ ...(recovered.head as PresentHead) }),
400			references,
401			trustRef: copiedRef(inspected.trustRef),
402		});
403	}
