405	async function persistSnapshot(
406		store: SnapshotQuarantineStore<SnapshotVerificationReceipt>,
407		input: Readonly<{
408			aclDigest: string;
409			anchor: string;
410			epoch: number;
411			exactCanonicalPayloadBytes: Uint8Array;
412			objectId: string;
413			stateDigest: string;
414		}>
415	): Promise<
416		Readonly<{
417			declaration: SnapshotQuarantineDeclaration;
418			exactCanonicalManifestBytes: Uint8Array;
419			manifestDigest: string;
420		}>
421	> {
422		const encoded = encodeSnapshotTransfer({ ...input, profile: PROFILE, schemaVersion: 1 });
423		const decoded = decodeSnapshotManifest({
424			exactCanonicalManifestBytes: encoded.exactCanonicalManifestBytes,
425			expectedManifestDigest: encoded.manifestDigest,
426			profile: PROFILE,
427		});
428		const scopeKey = Object.freeze({
429			anchor: input.anchor,
430			epoch: input.epoch,
431			manifestDigest: encoded.manifestDigest,
432			objectId: input.objectId,
433		});
434		const scope = await store.openScope({
435			chunks: decoded.chunks,
436			exactCanonicalManifestBytes: encoded.exactCanonicalManifestBytes,
437			scope: scopeKey,
438			totalBytes: decoded.chunks.reduce((total, chunk) => total + chunk.byteLength, 0),
439		});
440		try {
441			const verified = verifySnapshotStreamWithReceipt({
442				exactCanonicalManifestBytes: encoded.exactCanonicalManifestBytes,
443				expectedManifestDigest: encoded.manifestDigest,
444				expectedScope: scopeKey,
445				profile: PROFILE,
446				quarantine: scope.verificationQuarantine,
447				source: Object.freeze({
448					read: (descriptor: Readonly<{ readonly index: number }>) =>
449						Promise.resolve(
450							encoded.chunks[descriptor.index] === undefined ? undefined : encoded.chunks[descriptor.index]
451						),
452				}),
453			});
454			await verified.completion;
455			await scope.complete(await verified.receipt);
456			return Object.freeze({
457				declaration: Object.freeze({
458					chunks: Object.freeze(decoded.chunks.map((chunk) => Object.freeze({ ...chunk }))),
459					exactCanonicalManifestBytes: Uint8Array.from(encoded.exactCanonicalManifestBytes),
460					scope: scopeKey,
461					totalBytes: decoded.chunks.reduce((total, chunk) => total + chunk.byteLength, 0),
462				}),
463				exactCanonicalManifestBytes: Uint8Array.from(encoded.exactCanonicalManifestBytes),
464				manifestDigest: encoded.manifestDigest,
465			});
466		} finally {
467			await scope.release();
468		}
469	}
