471	async function stageCombinedGeneration(
472		store: AheDurableStore,
473		current: Awaited<ReturnType<typeof inspectHead>>,
474		newBlobs: readonly Readonly<{ bytes: Uint8Array; ref: GenerationRef }>[],
475		proposed: readonly GenerationRef[]
476	): Promise<PresentHead> {
477		const selectedGenerationId = generationId();
478		const closureDigest = digestClosure(proposed);
479		if (!closureDigest.ok) throw new TypeError("creator close closure digest failed");
480		const begun = successfulValue<Readonly<{ readonly closureDigest: string }>>(
481			await store.beginGeneration({
482				baseExpectedHead: current.head,
483				closure: proposed,
484				generationId: selectedGenerationId,
485				objectId: current.head.objectId,
486			})
487		);
488		if (begun?.closureDigest !== closureDigest.value) throw new TypeError("creator close generation staging failed");
489		for (const blob of newBlobs) {
490			const cached = successfulValue<Readonly<{ readonly inserted: boolean }>>(
491				await store.putCachedBlob({
492					bytes: blob.bytes,
493					digest: blob.ref.digest,
494					generationId: selectedGenerationId,
495					objectId: current.head.objectId,
496				})
497			);
498			if (cached === undefined) throw new TypeError("creator close blob staging failed");
499		}
500		for (const ref of proposed) {
501			const promoted = await store.promoteReference({
502				digest: ref.digest,
503				generationId: selectedGenerationId,
504				objectId: current.head.objectId,
505			});
506			if (!successfulUndefined(promoted)) throw new TypeError("creator close reference promotion failed");
507		}
508		const completed = successfulValue<Readonly<{ readonly closureDigest: string }>>(
509			await store.completeGeneration({ generationId: selectedGenerationId, objectId: current.head.objectId })
510		);
511		if (completed?.closureDigest !== closureDigest.value)
512			throw new TypeError("creator close generation completion failed");
513		let swapped: PresentHead | undefined;
514		try {
515			const result = successfulValue<Readonly<{ readonly head: PresentHead }>>(
516				await store.swapHead({
517					expectedHead: current.head,
518					generationId: selectedGenerationId,
519					objectId: current.head.objectId,
520				})
521			);
522			swapped = result?.head;
523		} catch {
524			// Reopen below decides whether an ambiguous write committed.
525		}
526		const reopened = await inspectHead(store, current.head.objectId);
527		const expected = Object.freeze({
528			closureDigest: closureDigest.value,
529			generationId: selectedGenerationId,
530			kind: "present" as const,
531			objectId: current.head.objectId,
532			revision: current.head.revision + 1,
533		}) as PresentHead;
534		if (!sameHead(reopened.head, expected) || (swapped !== undefined && !sameHead(swapped, expected))) {
535			throw new TypeError("creator close head swap lost or remained ambiguous");
536		}
537		return reopened.head;
538	}
