545	export async function bindCreatorLiveClose(
546		input: BindCreatorLiveCloseInput
547	): Promise<Readonly<{ handle: CreatorLiveCloseHandle; ok: true } | { ok: false; reason: string }>> {
548		try {
549			const existing = bindings.get(input.plane);
550			if (existing !== undefined) return Object.freeze({ handle: existing, ok: true as const });
551			const registration = claimCreatorCloseRegistration(input.plane);
552			if (registration === undefined) return Object.freeze({ ok: false as const, reason: "CREATOR_CLOSE_UNAVAILABLE" });
553			const epoch = registration.currentTrust.currentEpoch;
554			if (!Number.isSafeInteger(epoch) || epoch < 0 || epoch === Number.MAX_SAFE_INTEGER) {
555				return Object.freeze({ ok: false as const, reason: "CREATOR_CLOSE_UNAVAILABLE" });
556			}
557			const successorEpoch = epoch + 1;
558			const boundHead = await inspectHead(registration.store, registration.objectId);
559			const boundTrustCandidate = boundHead.candidates.find(({ ref }) => sameRef(ref, boundHead.trustRef));
560			if (
561				boundTrustCandidate === undefined ||
562				verifiedCreatorTrustRecord(registration, boundTrustCandidate.bytes) === undefined
563			) {
564				return Object.freeze({ ok: false as const, reason: "CREATOR_TRUST_UNAVAILABLE" });
565			}
566			const opened = await createCreatorSealActor({
567				currentTrust: registration.currentTrust,
568				evidenceStore: input.evidenceStore,
569				onObservation: input.onObservation,
570				signer: input.signer,
571				storageIncarnation: input.storageIncarnation,
572				voteStore: input.voteStore,
573			});
